CREATE TRIGGER RefCusQuota_Version_Create
	ON RefCusQuota
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ZXQ_PK, 'ZXQ'
	FROM inserted
GO
CREATE TRIGGER RefCusQuota_Version_Update
	ON RefCusQuota
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ZXQ_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefCusQuota_DataChangeHistory
	ON RefCusQuota
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT ZXQ_PK, 'ZXQ' FROM inserted
	UNION
	SELECT ZXQ_PK, 'ZXQ' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefCusQuota_DataProcessingResult_Delete
	ON RefCusQuota
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZXQ_PK
	END
